 "recipeIngredient": [
  "1/2 cup cooked Rice",
  "1 cup water",
  "1/4 cup curds , homemade",
  "3/4 tsp salt or as required",
  "1 tbsp fresh coriander leaves , chopped",
  "1/2 tbsp coconut oil",
  "1/4 tsp mustard seeds",
  "1/4 tsp jeera / cumin Seeds",
  "1/2 tsp urad dal / split black gram",
  "1 tsp curry leaves ,finely chopped",
  "1/2 tsp green chilies , chopped",
  "4 tbsp onion ,finely chopped",
  "1 tsp ginger , grated",
  "1/2 tsp Asafoetida / Hing"
 ],
 "recipeInstructions": [
  {
   "@type": "HowToStep",
   "text": "Soak 1/2 cup cooked rice in 1/2 cup water in a clay pot for about 10-12 hours or overnight.",
   "name": "Soak 1/2 cup cooked rice in 1/2 cup water in a clay pot for about 10-12 hours or overnight.",
   "url": "https://palatesdesire.com/rice-kanji-homemade-probiotics/#wprm-recipe-8782-step-0-0"
  },
  {
   "@type": "HowToStep",
   "text": "Next day , transfer fermented rice to a blender and blend to smooth paste.",
   "name": "Next day , transfer fermented rice to a blender and blend to smooth paste.",
   "url": "https://palatesdesire.com/rice-kanji-homemade-probiotics/#wprm-recipe-8782-step-0-1"
  },
  {
   "@type": "HowToStep",
   "text": "Transfer blended rice into a mixing bowl.",
   "name": "Transfer blended rice into a mixing bowl.",
   "url": "https://palatesdesire.com/rice-kanji-homemade-probiotics/#wprm-recipe-8782-step-0-2"
  },
  {
   "@type": "HowToStep",
   "text": "Whisk 1/4 cup of homemade curds and add to rice paste and stir well. Preferably add slightly sour curds as it tastes more good.",
   "name": "Whisk 1/4 cup of homemade curds and add to rice paste and stir well. Preferably add slightly sour curds as it tastes more good.",
   "url": "https://palatesdesire.com/rice-kanji-homemade-probiotics/#wprm-recipe-8782-step-0-3"
  },
  {
   "@type": "HowToStep",
   "text": "Now add salt to taste and mix well.",
   "name": "Now add salt to taste and mix well.",
   "url": "https://palatesdesire.com/rice-kanji-homemade-probiotics/#wprm-recipe-8782-step-0-4"
  },
  {
   "@type": "HowToSection",
   "name": "To temper",
   "itemListElement": [
    {
     "@type": "HowToStep",
     "text": "In a season pan / tadka pan , heat coconut oil , add mustard seeds ,jeera seeds , urad dal ,  chopped curry leaves , choppeds green chillies  and fry well.",
     "name": "In a season pan / tadka pan , heat coconut oil , add mustard seeds ,jeera seeds , urad dal ,  chopped curry leaves , choppeds green chillies  and fry well.",
     "url": "https://palatesdesire.com/rice-kanji-homemade-probiotics/#wprm-recipe-8782-step-1-0"
    },
    {
     "@type": "HowToStep",
     "text": "Add chopped onions and fry till it turns light brown .Turn off the stove",
     "name": "Add chopped onions and fry till it turns light brown .Turn off the stove",
     "url": "https://palatesdesire.com/rice-kanji-homemade-probiotics/#wprm-recipe-8782-step-1-1"
    },
    {
     "@type": "HowToStep",
     "text": "Now add in grated ginger , hing  and mix well.",
     "name": "Now add in grated ginger , hing  and mix well.",
     "url": "https://palatesdesire.com/rice-kanji-homemade-probiotics/#wprm-recipe-8782-step-1-2"
    },
    {
     "@type": "HowToStep",
     "text": "Pour temper over the prepared rice kanji.",
     "name": "Pour temper over the prepared rice kanji.",
     "url": "https://palatesdesire.com/rice-kanji-homemade-probiotics/#wprm-recipe-8782-step-1-3"
